SELECT
    sale_time,
    LAG(sale_time) OVER (
        ORDER BY sale_time
    ) AS previous_sale
FROM sales;

SELECT
    sale_time,
    sale_time - LAG(sale_time) OVER (
        ORDER BY sale_time
    ) AS time_since_previous
FROM sales;

SELECT
    sale_time,
    LEAD(sale_time) OVER (
        ORDER BY sale_time
    ) AS next_sale
FROM sales;

SELECT AVG(time_between)
FROM (
    SELECT
        sale_time - LAG(sale_time) OVER (
            ORDER BY sale_time
        ) AS time_between
    FROM sales
) AS gaps;

SELECT AVG(resolution_time)
FROM (
    SELECT resolved_at - created_at AS resolution_time
    FROM tickets
) t;

SELECT AVG(time_between)
FROM (
    SELECT
        customer_id,
        order_time - LAG(order_time) OVER (
            PARTITION BY customer_id
            ORDER BY order_time
        ) AS time_between
    FROM orders
) t;

