SELECT
    COUNT(*) AS total_students,
    COUNT(gpa) AS students_with_gpa,
    COUNT(*) - COUNT(gpa) AS missing_gpa
FROM students;

-- Step 2: Range
SELECT MIN(gpa) AS min_gpa, MAX(gpa) AS max_gpa FROM students;

-- Step 3: Distribution
SELECT gpa, COUNT(*) AS n FROM students GROUP BY gpa ORDER BY gpa;

-- Range
SELECT MIN(x), MAX(x) FROM table_name;

-- Mean
SELECT AVG(x) FROM table_name;

-- Variance / Std Dev
SELECT VAR_SAMP(x), STDDEV_SAMP(x) FROM table_name;

-- Median
SELECT PERCENTILE_CONT(0.5)
       WITHIN GROUP (ORDER BY x)
FROM table_name;

-- Correlation
SELECT CORR(x, y) FROM table_name;

-- Safe percentage
SELECT 100.0 * AVG(CASE WHEN condition THEN 1 ELSE 0 END)
FROM table_name;

